/* ghostcn: Post Card Styles */
.gh-post-card {
    box-sizing: border-box;
    font-family: inherit;
    font-size: 16px;
    line-height: 1.5;
    isolation: isolate;
    background-color: var(--card, #ffffff);
    color: var(--card-foreground, #09090b);
    border: 1px solid var(--border, #e4e4e7);
    border-radius: min(var(--radius, 0.5em), 1.5em);
    overflow: hidden;
    display: flex;
    flex-direction: column;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
    box-shadow: 0 1px 3px 0 rgba(0, 0, 0, 0.05);
}

.gh-post-card *,
.gh-post-card *::before,
.gh-post-card *::after {
    box-sizing: border-box;
}

.gh-post-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1);
}

.gh-post-card-image {
    aspect-ratio: 16 / 9;
    overflow: hidden;
    display: block;
    background-color: var(--muted, #f4f4f5);
}

.gh-post-card-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.3s ease;
}

.gh-post-card:hover .gh-post-card-image img {
    transform: scale(1.03);
}

.gh-post-card-content {
    padding: 1.25em;
    flex: 1;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
}

.gh-post-card-tag {
    color: var(--primary, var(--ghost-accent-color, #18181b));
    font-size: 0.75em;
    font-weight: 600;
    text-decoration: none;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.gh-post-card-tag:hover {
    text-decoration: underline;
}

.gh-post-card-title {
    font-size: 1.25em;
    font-weight: 700;
    letter-spacing: -0.025em;
    margin: 0.5em 0;
    line-height: 1.35;
}

.gh-post-card-title a {
    color: var(--foreground, #09090b);
    text-decoration: none;
    transition: color 0.15s ease;
}

.gh-post-card-title a:hover {
    color: var(--primary, var(--ghost-accent-color, #18181b));
}

.gh-post-card-excerpt {
    color: var(--muted-foreground, #71717a);
    font-size: 0.875em;
    line-height: 1.5;
    margin-bottom: 1em;
}

.gh-post-card-footer {
    padding-top: 1em;
    border-top: 1px solid var(--border, #e4e4e7);
    display: flex;
    justify-content: space-between;
    font-size: 0.75em;
    color: var(--muted-foreground, #71717a);
}
